INSERT OR REPLACE INTO template_genjutsu (template_id, tool, source_key, secs, prompt, roles) VALUES
('sortie-sportive', 'motion-transfer', 'templates/sortie-sportive/source.mp4', 5.00, 'WHO IS WHO: the person in the input video = PERSON A from the photo. The man stepping out of the red sports car becomes PERSON A. Replace the whole person — head, face, hair, body, arms, hands, legs — at the same position, size in frame, pose and timing, copying every movement, gesture, head turn and expression frame by frame, including the camera moves. FACES FIRST: the same real face as in the photos in every shot, bare open eyes, nothing added on the face; own hair and body proportions from the photos. Wearing the same light outfit as in the input, fitted to their own body. Keep the background, lighting, camera and everything else exactly as in the input.', '["Votre photo"]'),
('demarche-ville', 'motion-transfer', 'templates/demarche-ville/source.mp4', 6.04, 'WHO IS WHO: the person in the input video = PERSON A from the photo. The woman walking down the street becomes PERSON A. Replace the whole person — head, face, hair, body, arms, hands, legs — at the same position, size in frame, pose and timing, copying every movement, gesture, head turn and expression frame by frame, including the camera moves. FACES FIRST: the same real face as in the photos in every shot, bare open eyes, nothing added on the face; own hair and body proportions from the photos. Wearing their own outfit from the photo. Keep the background, lighting, camera and everything else exactly as in the input.', '["Votre photo"]'),
('pose-times-square', 'motion-transfer', 'templates/pose-times-square/source.mp4', 7.04, 'WHO IS WHO: the person in the input video = PERSON A from the photo. The man walking and posing in Times Square becomes PERSON A. Replace the whole person — head, face, hair, body, arms, hands, legs — at the same position, size in frame, pose and timing, copying every movement, gesture, head turn and expression frame by frame, including the camera moves. FACES FIRST: the same real face as in the photos in every shot, bare open eyes, nothing added on the face; own hair and body proportions from the photos. Wearing their own outfit from the photo. Keep the background, lighting, camera and everything else exactly as in the input.', '["Votre photo"]'),
('look-du-jour', 'motion-transfer', 'templates/look-du-jour/source.mp4', 6.79, 'WHO IS WHO: the person in the input video = PERSON A from the photo. The woman in the room becomes PERSON A in every shot. Replace the whole person — head, face, hair, body, arms, hands, legs — at the same position, size in frame, pose and timing, copying every movement, gesture, head turn and expression frame by frame, including the camera moves. FACES FIRST: the same real face as in the photos in every shot, bare open eyes, nothing added on the face; own hair and body proportions from the photos. Wearing their own outfit from the photo, keeping the hat and the bag of the input. Keep the background, lighting, camera and everything else exactly as in the input.', '["Votre photo"]'),
('street-style-nyc', 'motion-transfer', 'templates/street-style-nyc/source.mp4', 13.12, 'WHO IS WHO: every model in every shot of the input video = PERSON A from the photo. Replace each model — head, face, hair, body, arms, hands, legs — at the same position, size in frame, pose and timing, copying every step, turn and expression frame by frame, across every cut. FACES FIRST: the same real face as in the photos in every shot, bare open eyes, nothing added on the face; own hair and body proportions from the photos. Keep each shot''s outfit style from the input, fitted to their own body. Keep the streets, light and camera moves exactly as in the input.', '["Votre photo"]'),
('gangster-annees-20', 'motion-transfer', 'templates/gangster-annees-20/source.mp4', 15.38, 'WHO IS WHO: the person in the input video = PERSON A from the photo. The man in the flat cap and long coat becomes PERSON A. Replace the whole person — head, face, hair, body, arms, hands, legs — at the same position, size in frame, pose and timing, copying every movement, gesture, head turn and expression frame by frame, including the camera moves. FACES FIRST: the same real face as in the photos in every shot, bare open eyes, nothing added on the face; own hair and body proportions from the photos. Wearing the same period suit, coat and flat cap as in the input, fitted to their own body. Keep the background, lighting, camera and everything else exactly as in the input.', '["Votre photo"]'),
('arrivee-en-rolls', 'motion-transfer', 'templates/arrivee-en-rolls/source.mp4', 15.00, 'WHO IS WHO: the passenger who gets out of the car = PERSON A from the photo. The chauffeur who opens the door stays exactly as in the input. Replace the passenger — head, face, hair, body, arms, hands, legs — at the same position, size in frame, pose and timing, copying every movement frame by frame. FACES FIRST: the same real face as in the photos in every shot, bare open eyes, nothing added on the face; own hair and body proportions from the photos. Wearing their own outfit from the photo. Keep the car, the street, the light and the camera exactly as in the input.', '["Votre photo"]'),
('pluie-de-billets', 'motion-transfer', 'templates/pluie-de-billets/source.mp4', 15.00, 'WHO IS WHO: the person in the input video = PERSON A from the photo. The young man counting and throwing banknotes becomes PERSON A. Replace the whole person — head, face, hair, body, arms, hands, legs — at the same position, size in frame, pose and timing, copying every movement, gesture, head turn and expression frame by frame, including the camera moves. FACES FIRST: the same real face as in the photos in every shot, bare open eyes, nothing added on the face; own hair and body proportions from the photos. Wearing their own outfit from the photo; keep the banknotes exactly as in the input. Keep the background, lighting, camera and everything else exactly as in the input.', '["Votre photo"]'),
('duo-en-studio', 'motion-transfer', 'templates/duo-en-studio/source.mp4', 16.00, 'WHO IS WHO: the man in the black suit (the singer) = PERSON A from the photos; the man in the white suit = PERSON B. Each person becomes the matching person from the photos — head, face, hair, body, arms, hands, legs — at the same position, size in frame, pose and timing, copying every gesture, lip movement, head turn and expression frame by frame. FACES FIRST: the same real faces as in the photos in every shot, bare open eyes, nothing added on the faces. Each keeps the suit colour of the input (black for A, white for B), fitted to their own body. Keep the orange studio, microphones, light and camera exactly as in the input.', '["Personne A, en noir (le chanteur)", "Personne B, en blanc"]'),
('balade-cabriolet', 'motion-transfer', 'templates/balade-cabriolet/source.mp4', 12.00, 'WHO IS WHO: the person in the input video = PERSON A from the photo. The woman driving the convertible becomes PERSON A. Replace the whole person — head, face, hair, body, arms, hands, legs — at the same position, size in frame, pose and timing, copying every movement, gesture, head turn and expression frame by frame, including the camera moves. FACES FIRST: the same real face as in the photos in every shot, bare open eyes, nothing added on the face; own hair and body proportions from the photos. Wearing their own outfit from the photo. Keep the background, lighting, camera and everything else exactly as in the input.', '["Votre photo"]'),
('defile-parking', 'motion-transfer', 'templates/defile-parking/source.mp4', 12.11, 'WHO IS WHO: the person in the input video = PERSON A from the photo. The young man in every shot becomes PERSON A, across every cut. Replace the whole person — head, face, hair, body, arms, hands, legs — at the same position, size in frame, pose and timing, copying every movement, gesture, head turn and expression frame by frame, including the camera moves. FACES FIRST: the same real face as in the photos in every shot, bare open eyes, nothing added on the face; own hair and body proportions from the photos. Wearing their own outfit from the photo, keeping the black sunglasses where the input has them. Keep the background, lighting, camera and everything else exactly as in the input.', '["Votre photo"]'),
('bande-passage-pieton', 'motion-transfer', 'templates/bande-passage-pieton/source.mp4', 14.04, 'WHO IS WHO: the man in the cap and striped jacket = PERSON A from the photos; the woman with curly hair and the red jacket = PERSON B; the man in the green hoodie = PERSON C. Any other passer-by stays as in the input. Each becomes the matching person from the photos — head, face, hair, body, arms, hands, legs — at the same position, size in frame, pose and timing, copying every move, gesture, head turn and expression frame by frame, across every cut. FACES FIRST: the same real faces as in the photos in every shot, bare open eyes, nothing added on the faces; their own clothes from the photos fitting their own bodies. Keep the street, the motorbike, the light and the camera exactly as in the input.', '["Personne A, casquette et veste rayée", "Personne B, cheveux bouclés et veste rouge", "Personne C, sweat vert"]'),
('trio-de-danse', 'motion-transfer', 'templates/trio-de-danse/source.mp4', 9.71, 'WHO IS WHO: the CENTRE dancer of the input = PERSON A from the photos; the LEFT dancer = PERSON B; the RIGHT dancer = PERSON C. The three front dancers become the matching people from the photos — head, face, hair, body, arms, hands, legs — at the same position, size in frame, pose and timing, copying every dance move, hand gesture, head turn and expression frame by frame, across every cut and whip pan. FACES FIRST: the same real faces as in the photos in every shot, bare open eyes, nothing added on the faces; their own clothes from the photos fitting their own bodies. The crowd stays as in the input.', '["Personne A, au centre", "Personne B, à gauche", "Personne C, à droite"]'),
('duo-en-voyage', 'motion-transfer', 'templates/duo-en-voyage/source.mp4', 9.38, 'WHO IS WHO: the man of the input = PERSON A from the photos; the woman = PERSON B. Both become the matching people from the photos — head, face, hair, body, arms, hands, legs — at the same position, size in frame, pose and timing, copying every move, gesture, head turn and expression frame by frame, across every cut. FACES FIRST: the same real faces as in the photos in every shot, bare open eyes, nothing added on the faces. Keep each shot''s outfits from the input, fitted to their own bodies. Keep the places, light and camera exactly as in the input.', '["Personne A, l’homme", "Personne B, la femme"]'),
('produit-en-main-genjutsu', 'object-swap', 'templates/produit-en-main-genjutsu/source.mp4', 16.50, 'Replace the jar of sweets held and shown in every shot with the product from the photos: its exact shape, colours, label and proportions, at the same position, size in frame, angle and motion, held the same way by the same hands, frame by frame across every cut. Keep the people, their faces and clothes, the rooms, light and camera exactly as in the input.', '["Photo de votre produit"]'),
('bouteille-de-fete', 'object-swap', 'templates/bouteille-de-fete/source.mp4', 7.21, 'Replace the champagne bottle with the bottle from the photos: its exact shape, colours, label and proportions, at the same position, size in frame, angle and motion, held and opened the same way, frame by frame. Keep the woman, her face, clothes and gestures, the garden, light and camera exactly as in the input.', '["Photo de votre bouteille"]');
